        ("            || self.glyph.as_ref().is_some_and(|glyph| glyph.lock.get().is_some())", "            || self.crossing_lock.get().is_some()\n            || self.glyph.as_ref().is_some_and(|glyph| glyph.lock.get().is_some())", 1),
        ("            return result;\n        }\n        let targets = self.targets(copy);", "            self.crossing_lock.set(None);\n            return result;\n        }\n        let targets = self.targets(copy);\n        if self.crossings && let Some(hit) = self.snap_crossing(targets, start, d, acquire, release, direction) {\n            self.lock.set(None);\n            self.x_lock.set(None);\n            self.y_lock.set(None);\n            return hit;\n        }", 1),
        ("/// Intersections must lie on BOTH finite paths.", "#[derive(Clone, Copy)]\nstruct MoveCrossing {\n    source: Point,\n    target: Point,\n    constrained: bool,\n}\n\nimpl ObjectMoveSnap {\n    fn snap_crossing(\n        &self, targets: &Targets, held: Point, delta: Vec2, acquire: f64, release: f64,\n        direction: Option<Vec2>,\n    ) -> Option<(Vec2, Vec<Overlay>)> {\n        let constrained = direction.is_some();\n        let allowed = |source: Point, target: Point| {\n            direction.is_none_or(|dir| on_direction(target - (source + delta), dir))\n        };\n        let previous = self.crossing_lock.get().filter(|lock| {\n            lock.constrained == constrained && (lock.source + delta).distance(lock.target) <= release\n                && allowed(lock.source, lock.target)\n        });\n        let hit = previous.or_else(|| {\n            // A deliberate grab wins. The selection centre remains usable when a\n            // hollow object was grabbed by its outline or the press missed the marker.\n            let center = self.bounds.map(|bounds| bounds.center()).filter(|p| *p != held);\n            std::iter::once(held).chain(center).find_map(|source| {\n                let raw = source + delta;\n                let target = targets.find_move_crossing(raw, acquire, &self.crossing_rulers, |q| allowed(source, q))?;\n                Some(MoveCrossing { source, target, constrained })\n            })\n        });\n        self.crossing_lock.set(hit);\n        let MoveCrossing { source, target, .. } = hit?;\n        let translation = if let Some(dir) = direction {\n            let unit = dir / dir.hypot();\n            delta + unit * (target - (source + delta)).dot(unit)\n        } else {\n            target - source\n        };\n        Some((translation, intersection_guides(targets, target, acquire, \"交点\")))\n    }\n}\n\nimpl Targets {\n    /// Only visible path geometry and ruler guides supply true move crossings.\n    fn find_move_crossing(\n        &self, p: Point, acquire: f64, rulers: &[super::Ruler], allowed: impl Fn(Point) -> bool,\n    ) -> Option<Point> {\n        let query = Rect::from_points(p, p).inflate(acquire, acquire);\n        let local = self.leo_scene.as_ref().map(|scene| scene.local_geometry(&[query], false));\n        let geometry = local.as_ref().unwrap_or(self);\n        let mut segments: Vec<PathSeg> = geometry.segments.iter()\n            .filter(|(bounds, _)| overlaps(*bounds, query)).map(|(_, seg)| *seg).collect();\n        for ruler in rulers {\n            let (lo, hi, axis) = if ruler.vertical { (query.y0, query.y1, p.x) } else { (query.x0, query.x1, p.y) };\n            if (ruler.pos - axis).abs() > acquire { continue; }\n            let (start, end) = ruler.span.map_or((lo, hi), |(a, b)| (lo.max(a), hi.min(b)));\n            if start >= end { continue; }\n            let point = |v| if ruler.vertical { Point::new(ruler.pos, v) } else { Point::new(v, ruler.pos) };\n            segments.push(PathSeg::Line(Line::new(point(start), point(end))));\n        }\n        let q = nearest_crossing(segments, p, acquire, allowed)?;\n        if geometry.leo_nearest_anchor(p, acquire).is_some_and(|a| a.distance(p) + 1e-7 < q.distance(p)) { return None; }\n        Some(q)\n    }\n}\n\n/// A selected cross may consist of separate paths, with no node at its centre.\npub(crate) fn grab_selection_crossing(cx: &ToolContext, p: Point, reach: f64) -> Option<Point> {\n    if !cx.leo_snapping || !cx.smart_guides || cx.snap_to_grid\n        || !cx.selection.anchors.is_empty() || !cx.selection.segments.is_empty()\n    {\n        return None;\n    }\n    nearest_crossing(selected_edges(cx), p, reach, |_| true)\n}\n\nfn nearest_crossing(segments: Vec<PathSeg>, p: Point, reach: f64, allowed: impl Fn(Point) -> bool) -> Option<Point> {\n    let query = Rect::from_points(p, p).inflate(reach, reach);\n    let epsilon = (reach * 1e-6).clamp(1e-10, 1e-7);\n    let mut nearby: Vec<_> = segments.into_iter().filter_map(|seg| {\n        let nearest = seg.nearest(p, epsilon);\n        (nearest.distance_sq <= reach * reach).then_some((seg, nearest.distance_sq))\n    }).collect();\n    nearby.sort_by(|a, b| a.1.total_cmp(&b.1));\n    // Keep pathological stacks of overlapping paths responsive during a drag.\n    nearby.truncate(32);\n    let mut best: Option<Point> = None;\n    for (i, (a, _)) in nearby.iter().enumerate() {\n        for (b, _) in nearby.iter().skip(i + 1) {\n            for q in finite_path_crossings(*a, *b, query, epsilon) {\n                if q.distance(p) <= reach && allowed(q) && best.is_none_or(|old| q.distance(p) < old.distance(p)) {\n                    best = Some(q);\n                }\n            }\n        }\n    }\n    best\n}\n\n/// Intersections must lie on BOTH finite paths.", 1),
        ("    #[test]\n    fn leo_object_move_snaps_source_anchor_to_target_anchor_exactly()", "    #[test]\n    fn leo_object_move_snaps_held_center_to_real_crossing() {\n        let mut targets = Targets::default();\n        for (a, b) in [\n            (Point::new(300.0, 200.0), Point::new(300.0, 400.0)),\n            (Point::new(200.0, 320.0), Point::new(400.0, 280.0)),\n            (Point::new(200.0, 360.0), Point::new(400.0, 330.0)),\n        ] {\n            targets.segments.push((Rect::from_points(a,b), PathSeg::Line(Line::new(a,b))));\n        }\n        let center = Point::new(150.0, 150.0);\n        let hit = Point::new(300.0, 300.0);\n        let snapper = move_snap(Rect::new(100.0, 100.0, 200.0, 200.0), vec![center], targets);\n        let (delta, guides) = snapper.snap_with_tolerance(center, Vec2::new(153.0, 152.0), false, 8.0, 12.8, None);\n        assert!((center + delta).distance(hit) < 1e-8);\n        assert!(guides.iter().any(|g| matches!(g, Overlay::CurvePoint { p, .. } if p.distance(hit) < 1e-8)));\n        let (_, guides) = snapper.snap_with_tolerance(center, Vec2::new(160.0, 150.0), false, 8.0, 12.8, None);\n        assert!(guides.iter().any(|g| matches!(g, Overlay::Label { text, .. } if text == \"交点\")));\n        let (_, guides) = snapper.snap_with_tolerance(center, Vec2::new(164.0, 150.0), false, 8.0, 12.8, None);\n        assert!(!guides.iter().any(|g| matches!(g, Overlay::Label { text, .. } if text == \"交点\")));\n    }\n\n    #[test]\n    fn leo_object_move_snaps_center_from_an_outline_grab_to_locked_ruler_crossing() {\n        let mut targets = Targets::default();\n        let a = Point::new(200.0, 320.0);\n        let b = Point::new(400.0, 280.0);\n        targets.segments.push((Rect::from_points(a, b), PathSeg::Line(Line::new(a, b))));\n        let bounds = Rect::new(100.0, 100.0, 200.0, 200.0);\n        let center = bounds.center();\n        let grabbed = Point::new(200.0, 150.0);\n        let mut doc = Document::new(600.0, 600.0);\n        doc.add_ruler_guide(&vectorcraft_doc::Guide::new(true, 300.0));\n        let selection = Selection::default();\n        let paint = crate::testutil::paint();\n        let cx = ToolContext {\n            guides: false, snap_to_point: false, leo_ruler_guides_visible: true,\n            ..crate::testutil::leo_cx(&doc, &selection, &paint)\n        };\n        let mut snapper = move_snap(bounds, vec![center], targets);\n        snapper.crossing_rulers = ObjectMoveSnap::new(&cx, Some(bounds)).crossing_rulers;\n        assert_eq!(snapper.crossing_rulers.len(), 1);\n        let (d, guides) = snapper.snap_with_tolerance(grabbed, Vec2::new(153.0, 152.0), false, 8.0, 12.8, None);\n        assert_eq!(center + d, Point::new(300.0, 300.0));\n        assert!(guides.iter().any(|g| matches!(g, Overlay::Label { text, .. } if text == \"交点\")));\n        let (d, _) = snapper.snap_with_tolerance(grabbed, Vec2::new(160.0, 150.0), false, 8.0, 12.8, None);\n        assert_eq!(center + d, Point::new(300.0, 300.0));\n        snapper.reset_locks();\n        snapper.crossing_rulers[0].span = Some((250.0, 295.0));\n        let (_, guides) = snapper.snap_with_tolerance(grabbed, Vec2::new(153.0, 152.0), false, 8.0, 12.8, None);\n        assert!(!guides.iter().any(|g| matches!(g, Overlay::Label { text, .. } if text == \"交点\")));\n    }\n\n    #[test]\n    fn leo_object_move_grabs_two_selected_lines_at_their_crossing() {\n        use crate::testutil::{cx, paint};\n        use vectorcraft_doc::Appearance;\n        let mut doc = Document::new(800.0, 600.0);\n        let layer = doc.layers[0].id;\n        let a = doc.alloc_id();\n        let b = doc.alloc_id();\n        let line = |id, p, q| Node::path(id, vectorcraft_geom::shapes::line(p, q), Appearance::default_art());\n        let cross = Point::new(130.0, 160.0);\n        doc.insert(Some(layer), 0, line(a, Point::new(100.0, 160.0), Point::new(200.0, 160.0))).unwrap();\n        doc.insert(Some(layer), 1, line(b, Point::new(130.0, 120.0), Point::new(130.0, 180.0))).unwrap();\n        let mut selection = Selection::default();\n        selection.set([a, b]);\n        let paint = paint();\n        let context = ToolContext { leo_snapping: true, ..cx(&doc, &selection, &paint) };\n        assert_eq!(grab_selection_crossing(&context, cross + Vec2::new(2.0, 1.0), 6.0), Some(cross));\n        let mut selection = Selection::default();\n        selection.set([a]);\n        let context = ToolContext { selection: &selection, ..context };\n        assert_eq!(grab_selection_crossing(&context, cross, 6.0), None);\n    }\n\n    #[test]\n    fn leo_object_move_snaps_source_anchor_to_target_anchor_exactly()", 1),
