        ("impl DirectSelectionTool {\n    /// A press at `p` takes a mesh point or handle,", "impl DirectSelectionTool {\n    /// The direction handle under the pointer or the one held by this drag.\n    fn direction_handle_feedback(&self, cx: &ToolContext) -> Option<(NodeId, Point, bool)> {\n        let (id, si, ai, out, grabbed) = match self.state {\n            State::Handle { id, si, ai, out } => (id, si, ai, out, true),\n            State::Idle if !self.guide.busy() => {\n                let p = self.bracket_hover?;\n                let tol = cx.point_tol();\n                if over_widget(cx, p, true)\n                    || (near_bracket(cx, p) && !over_path_type_anchor(cx, p))\n                    || self.mesh.hit(cx, &cx.selection.objects, p).is_some()\n                    || self.spine.filter(|(id, _)| cx.selection.contains(*id))\n                        .is_some_and(|sel| hit_spine_handle(cx, sel, p, tol).is_some())\n                {\n                    return None;\n                }\n                let (id, si, ai, out) = hit_handle(cx, p, tol)?;\n                (id, si, ai, out, false)\n            }\n            _ => return None,\n        };\n        let path = handle_path(cx.doc.node(id)?)?;\n        let anchor = path.subpaths.get(si)?.anchors.get(ai)?;\n        let end = if out { anchor.h_out } else { anchor.h_in };\n        Some((id, end, grabbed))\n    }\n    /// A press at `p` takes a mesh point or handle,", 1),
