        ("    assert!(handle(&c, 101.0, 251.0), \"the first anchor's handle, the path selected whole\");\n    let mut t = DirectSelectionTool::new(false);\n    t.pointer(&c, &PointerEvent::new(PointerKind::Down, 101.0, 251.0));", "    assert!(handle(&c, 101.0, 251.0), \"the first anchor's handle, the path selected whole\");\n    let mut t = DirectSelectionTool::new(false);\n    let rings = |tool: &DirectSelectionTool| {\n        tool.overlays(&c).into_iter().filter_map(|overlay| match overlay {\n            Overlay::CurvePoint { p, color: [32, 37, 46], size, .. } => Some((p, size)),\n            _ => None,\n        }).collect::<Vec<_>>()\n    };\n    assert!(rings(&t).is_empty());\n    t.pointer(&c, &PointerEvent::new(PointerKind::Move, 101.0, 251.0));\n    assert_eq!(rings(&t), [(Point::new(100.0, 250.0), 10.0)]);\n    t.pointer(&c, &PointerEvent::new(PointerKind::Down, 101.0, 251.0));\n    assert_eq!(rings(&t), [(Point::new(100.0, 250.0), 12.0)]);", 1),
